package com.hms.model;

import com.fasterxml.jackson.annotation.JsonProperty;
import org.springframework.data.annotation.CreatedDate;
import org.springframework.data.annotation.Id;
import org.springframework.data.annotation.LastModifiedDate;
import org.springframework.data.mongodb.core.mapping.Document;

import java.time.Instant;

/**
 * Represents a patient in the hospital.
 * Maps to the "patients" MongoDB collection.
 *
 * Key design decisions:
 *
 * 1. patientId (e.g., "P0001") — human-readable sequential ID generated by CounterService.
 *    Separate from the MongoDB "_id" (ObjectId). The frontend uses both:
 *    "_id" for database references, "patientId" for display.
 *
 * 2. user (String) — stores the ObjectId string of the linked User account.
 *    Some patients are registered by receptionists before they have login accounts,
 *    so this field can be null. It mirrors Mongoose's ObjectId reference.
 *
 * 3. emergencyContact — an embedded object (not a separate collection).
 *    In Java, we model this as an inner static class.
 */
@Document(collection = "patients")
public class Patient {

    @Id
    @JsonProperty("_id")
    private String id;

    /** Human-readable ID: P0001, P0002, etc. Generated by CounterService. */
    private String patientId;

    /** ObjectId string of the linked User account. Null if no login yet. */
    private String user;

    private String name;
    private String dob;     // stored as "YYYY-MM-DD" string to avoid timezone issues
    private String gender;  // "Male", "Female", "Other"
    private String phone;
    private String email;
    private String address;
    private String bloodGroup; // "A+", "A-", "B+", "B-", "AB+", "AB-", "O+", "O-", ""
    private EmergencyContact emergencyContact;
    private String allergies;

    @CreatedDate
    private Instant createdAt;

    @LastModifiedDate
    private Instant updatedAt;

    // ---------------------------------------------------------------
    // Inner class: EmergencyContact (embedded document)
    // ---------------------------------------------------------------

    /**
     * Embedded document for emergency contact information.
     * Stored as a nested object inside the patient document, not a separate collection.
     * Equivalent to Mongoose's sub-schema: { name: String, phone: String }
     */
    public static class EmergencyContact {
        private String name;
        private String phone;

        public EmergencyContact() {}

        public EmergencyContact(String name, String phone) {
            this.name = name;
            this.phone = phone;
        }

        public String getName() { return name; }
        public void setName(String name) { this.name = name; }

        public String getPhone() { return phone; }
        public void setPhone(String phone) { this.phone = phone; }
    }

    // ---------------------------------------------------------------
    // Constructors
    // ---------------------------------------------------------------

    public Patient() {}

    // ---------------------------------------------------------------
    // Getters and Setters
    // ---------------------------------------------------------------

    public String getId() { return id; }
    public void setId(String id) { this.id = id; }

    public String getPatientId() { return patientId; }
    public void setPatientId(String patientId) { this.patientId = patientId; }

    public String getUser() { return user; }
    public void setUser(String user) { this.user = user; }

    public String getName() { return name; }
    public void setName(String name) { this.name = name; }

    public String getDob() { return dob; }
    public void setDob(String dob) { this.dob = dob; }

    public String getGender() { return gender; }
    public void setGender(String gender) { this.gender = gender; }

    public String getPhone() { return phone; }
    public void setPhone(String phone) { this.phone = phone; }

    public String getEmail() { return email; }
    public void setEmail(String email) { this.email = email; }

    public String getAddress() { return address; }
    public void setAddress(String address) { this.address = address; }

    public String getBloodGroup() { return bloodGroup; }
    public void setBloodGroup(String bloodGroup) { this.bloodGroup = bloodGroup; }

    public EmergencyContact getEmergencyContact() { return emergencyContact; }
    public void setEmergencyContact(EmergencyContact emergencyContact) { this.emergencyContact = emergencyContact; }

    public String getAllergies() { return allergies; }
    public void setAllergies(String allergies) { this.allergies = allergies; }

    public Instant getCreatedAt() { return createdAt; }
    public void setCreatedAt(Instant createdAt) { this.createdAt = createdAt; }

    public Instant getUpdatedAt() { return updatedAt; }
    public void setUpdatedAt(Instant updatedAt) { this.updatedAt = updatedAt; }
}
